import {useEffect,useRef,useState} from 'react';
import {ApiError,request,createAttempt,readPending,rememberPending,forgetPending,commandResult,keepAttempt,type Attempt} from './api';
import {type Row,type Sede,type Page,text,money,today,canonicalDecimal,decimal} from './domain';
import {CommandForm,DataTable,List,Notice,State,useResource,Field,Amount} from './ui';
import {toneOf} from './tone';
const when=(v:unknown)=>{const d=typeof v==='string'?new Date(v):undefined;return d&&!isNaN(d.getTime())?new Intl.DateTimeFormat('es-MX',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Mexico_City'}).format(d):'No informado';};
import {FormField,PartyField,str,cash} from './App';
import {operationAnimals,replaceLot} from './workflow';
import type {components} from './generated/api-schema';
export function PeriodFields({base}:{base:string}){const r=useResource<Page>(base+'/periodos?pagina=1&tamano=100');return <><FormField name="periodo_id" label="Periodo económico" options={r.data?.elementos.filter(p=>p.estado==='ABIERTO').map(p=>({value:String(p.id),label:text(p.nombre||p.codigo||p.id)}))||[]}/><FormField name="fecha_reconocimiento" label="Fecha de reconocimiento" type="date" initial={today()}/>{r.error&&<Notice error={r.error}/>}</>;}
function inputDecimal(value:unknown){return value&&typeof value==='object'&&'importe' in value?String(value.importe):value===undefined?'':String(value);}
export const recognition=(f:FormData)=>({periodo_id:str(f,'periodo_id'),fecha_reconocimiento:str(f,'fecha_reconocimiento')});
export function OperationEditor({base,sede,id,go}:{base:string;sede:Sede;id:string;go:(next:string,row?:Row)=>void}){
    const path=base+'/operaciones/'+id;const [rev,setRev]=useState(0);const r=useResource<Row>(path,rev);const [step,setStep]=useState('condiciones');const [ticket,setTicket]=useState<Row>();const bump=()=>setRev(n=>n+1);const selectedTicket=((r.data?.pesajes as Row[])||[]).find(p=>p.id===ticket?.id)||ticket;
    const positions=useSalePositions(base,r.data);const operator=sede.roles.some(x=>['ADMIN','OPERADOR'].includes(x));
    return <><section className="panel"><div className="section-heading"><h2>{text(r.data?.folio||'Expediente de operación')}</h2><button className="secondary" onClick={r.reload}>Recargar versión</button></div><State {...r}>{r.data&&<><dl className="facts"><div><dt>Operación</dt><dd>{text(r.data.tipo)} · {text(r.data.estado)}</dd></div><div><dt>Entrega física</dt><dd>{text(r.data.estado_entrega)}</dd></div><div><dt>Contraparte</dt><dd>{text(r.data.contraparte)}</dd></div><div><dt>Versión</dt><dd>{text(r.data.version_lock)}</dd></div></dl><details className="contract-versions"><summary>Versiones de condiciones ({((r.data.contratos as Row[])||[]).length})</summary><DataTable rows={r.data.contratos as Row[]||[]} columns={[{key:'numero_version',label:'Versión'},{key:'estado',label:'Estado'},{key:'aceptada_en',label:'Aceptada'},{key:'requiere_recepcion',label:'Recepción pendiente'}]}/></details><nav className="stepper" aria-label="Pasos de la operación">{[['condiciones','1 · Ganado y precio'],['pesaje','2 · Pesaje'],['revision','3 · Revisar y confirmar']].map(([value,label])=><button className={step===value?'current':''} aria-current={step===value?'step':undefined} key={value} onClick={()=>setStep(value)}>{label}</button>)}</nav>{r.data.estado==='CONFIRMADA'?<div className="notice success">El cierre económico está confirmado. La recepción, entrega y pago se registran por separado.<button className="text-button" onClick={()=>go('liquidaciones',r.data?.liquidacion_id?{id:String(r.data.liquidacion_id)}:undefined)}>Consultar liquidación</button></div>:!operator?<p>Consulta de solo lectura para tu rol.</p>:step==='condiciones'?<LotForm key={rev} base={base} path={path} operation={r.data} etag={r.etag||`"${r.data.version_lock}"`} bump={bump}/>:step==='pesaje'?<><h3>Proponer ticket de báscula</h3><CommandForm path={path+'/pesajes'} label="Registrar propuesta de pesaje" build={f=>({numero_lote:Number(str(f,'numero_lote')),modo:'NETO_REPORTADO',neto:{kg:canonicalDecimal(str(f,'neto'),3)},pesado_en:new Date(str(f,'pesado_en')).toISOString(),ticket_folio:str(f,'ticket_folio'),documento_id:str(f,'documento_id')||undefined,animales:operationAnimals({...r.data,lotes:((r.data!.lotes as Row[])||[]).filter(l=>l.numero_lote===Number(str(f,'numero_lote')))},positions.data).map(animal_id=>({animal_id,...(str(f,'peso_'+animal_id)?{peso_individual:{kg:canonicalDecimal(str(f,'peso_'+animal_id),3)}}:{})}))})} onDone={data=>{setTicket(data);bump();}}><div className="form-grid"><FormField name="numero_lote" label="Lote a pesar" initial="1" options={((r.data.lotes as Row[])||[]).map(l=>({value:String(l.numero_lote),label:"Lote "+text(l.numero_lote)}))}/><FormField name="neto" label="Peso neto reportado en kg" help="El ticket conserva la composición del lote; no se calcula un descuento."/><FormField name="ticket_folio" label="Folio del ticket"/><FormField name="pesado_en" label="Fecha y hora del pesaje" type="datetime-local"/><FormField name="documento_id" label="Documento de evidencia" required={false}/></div>{positions.loading&&<p role="status">Consultando composición animal de la venta…</p>}<Notice error={positions.error}/><h3>Pesos individuales medidos (opcionales)</h3><p className="muted">Registra sólo pesos individuales realmente medidos. No se infieren del total del lote.</p><div className="form-grid">{!positions.loading&&!positions.error&&operationAnimals(r.data,positions.data).map(animal_id=><FormField key={animal_id} name={'peso_'+animal_id} label={'Peso en kg · '+animal_id} required={false}/>)}</div></CommandForm>{ticket&&<div className="subpanel"><h3>Propuesta registrada · {text(ticket.id)}</h3><p>Estado: {text(selectedTicket?.estado)} · {text(selectedTicket?.neto)}</p>{selectedTicket?.estado!=='APROBADO'&&<CommandForm path={base+'/pesajes/'+ticket.id+'/aprobar'} label="Aprobar pesaje revisado" build={()=>({})} onDone={bump}><p>Revisa el ticket y la composición antes de aprobar. Después vincula este identificador al lote: <strong>{text(ticket.id)}</strong>.</p></CommandForm>}</div>}</>:<><h3>Revisión del cierre económico</h3><DataTable rows={r.data.lotes as Row[]||[]} columns={[{key:'numero_lote',label:'Lote'},{key:'unidad_precio',label:'Unidad'},{key:'precio_unitario',label:'Precio pactado'},{key:'pesaje_base_id',label:'Pesaje base'}]}/><p className="notice">Confirmar genera inventario y obligación en una sola transacción. El servidor comprueba partidas, pesos, condiciones y reservas. No se enviarán totales del navegador.</p><CommandForm path={path+'/confirmar'} etag={r.etag||`"${r.data.version_lock}"`} label={'Confirmar '+text(r.data.tipo).toLowerCase()} build={recognition} onDone={data=>go('liquidaciones',{id:String(data.liquidacion_id||data.id)})}><div className="form-grid"><PeriodFields base={base}/></div></CommandForm></>}</>}</State></section>{r.data?.tipo==='VENTA'&&r.data.estado!=='CONFIRMADA'&&operator&&<section className="panel"><h2>Reserva para esta venta</h2><p>Reserva las posiciones guardadas antes de confirmar. Una reserva vencida necesita nueva revisión.</p><CommandForm path={path+'/reservas'} label="Reservar posiciones" build={f=>({posiciones:((r.data?.lotes as Row[])||[]).flatMap(l=>l.posiciones as string[]||[]),vence_en:new Date(str(f,'vence_en')).toISOString()})} onDone={bump}><FormField name="vence_en" label="Vencimiento de reserva" type="datetime-local"/></CommandForm></section>}</>;
}
function useSalePositions(base:string,operation:Row|undefined){
    const [state,setState]=useState<{data:Row[];loading:boolean;error?:Error}>({data:[],loading:false});
    const identity=operation?.tipo==='VENTA'?JSON.stringify(((operation.lotes as Row[])||[]).flatMap(l=>l.posiciones as string[]||[])):'';
    useEffect(()=>{let active=true;const controller=new AbortController();if(!operation)return;if(!identity){setState({data:[],loading:false});return;}const wanted=new Set(JSON.parse(identity) as string[]);setState({data:[],loading:true});
        async function load(){let rows:Row[]=[];for(let page=1;;page++){const {data}=await request<Page>(base+'/inventario/posiciones?pagina='+page+'&tamano=100',{signal:controller.signal});rows.push(...data.elementos.filter(p=>wanted.has(String(p.id))));if(rows.length>=wanted.size||page*data.tamano>=data.total)break;}operationAnimals({tipo:'VENTA',lotes:[{posiciones:[...wanted]}]},rows);return rows;}
        load().then(data=>{if(active)setState({data,loading:false});}).catch(error=>{if(active)setState({data:[],loading:false,error});});return()=>{active=false;controller.abort();};
    },[base,identity]);return state;
}
function LotForm(props:{base:string;path:string;operation:Row;etag:string;bump:()=>void}){
    const lots=(props.operation.lotes as Row[])||[];const [lotNumber,setLotNumber]=useState(Number(lots[0]?.numero_lote||1));
    if(props.operation.estado==='ACORDADA')return <><h3>Condiciones aceptadas</h3><p className="notice">El acuerdo conserva sus condiciones. Reabrir crea una propuesta editable sin borrar versiones anteriores.</p><DataTable rows={lots} columns={[{key:'numero_lote',label:'Lote'},{key:'unidad_precio',label:'Unidad'},{key:'precio_unitario',label:'Precio pactado'}]}/><CommandForm path={props.path+'/reabrir'} etag={props.etag} label="Reabrir condiciones" build={()=>({})} onDone={props.bump}><p>La reapertura requiere una revisión nueva antes de confirmar.</p></CommandForm></>;
    return <><nav className="stepper" aria-label="Lotes de la operación">{lots.map(l=><button key={String(l.numero_lote)} className={l.numero_lote===lotNumber?'current':''} onClick={()=>setLotNumber(Number(l.numero_lote))}>Lote {text(l.numero_lote)}</button>)}<button onClick={()=>setLotNumber(Math.max(0,...lots.map(l=>Number(l.numero_lote)))+1)}>+ Añadir lote</button></nav><LotEditor key={lotNumber} {...props} lotNumber={lotNumber}/><CommandForm path={props.path+'/acordar'} etag={props.etag} label="Aceptar condiciones" build={()=>({})} onDone={props.bump}><p>Revisa todos los lotes antes de aceptar. El acuerdo se conserva como una versión inmutable.</p></CommandForm></>;
}
function LotEditor({base,path,operation,etag,bump,lotNumber}:{base:string;path:string;operation:Row;etag:string;bump:()=>void;lotNumber:number}){
    const sale=operation.tipo==='VENTA';const [query,setQuery]=useState('');const [search,setSearch]=useState('');const source=useResource<Page>(base+(sale?'/inventario/posiciones':'/animales')+'?pagina=1&tamano=100'+(search?'&q='+encodeURIComponent(search):''));const lot=((operation.lotes as Row[])||[]).find(l=>l.numero_lote===lotNumber)||{};const [selection,setSelection]=useState<string[]>((sale?lot.posiciones:lot.animales) as string[]||[]);
    return <><h3>Composición y condiciones del lote</h3><p className="muted">Selecciona los animales o posiciones, guarda las condiciones y continúa al pesaje.</p><CommandForm path={path} method="PATCH" etag={etag} label="Guardar condiciones del lote" build={f=>({lotes:replaceLot((operation.lotes as Row[])||[],{numero_lote:lotNumber,...(sale?{posiciones:selection}:{animales:selection}),unidad_precio:str(f,'unidad_precio'),precio_unitario:canonicalDecimal(str(f,'precio_unitario'),4),pesaje_base_id:str(f,'pesaje_base_id')||undefined,deduccion_pct:str(f,'deduccion_pct')?canonicalDecimal(str(f,'deduccion_pct'),6):undefined,cargos_pactados:str(f,'cargos_pactados')?canonicalDecimal(str(f,'cargos_pactados'),2):undefined,bonificaciones_pactadas:str(f,'bonificaciones_pactadas')?canonicalDecimal(str(f,'bonificaciones_pactadas'),2):undefined}),requiere_recepcion:f.has('requiere_recepcion')})} onDone={bump}><div className="list-filters"><Field name="busqueda_ganado" label="Buscar ganado por identidad o código" required={false} value={query} onChange={setQuery}/><button type="button" className="secondary" onClick={()=>setSearch(query.trim())}>Buscar ganado</button></div><State {...source} empty={!source.data?.elementos.length}><div className="selection-list">{source.data?.elementos.map(a=><label key={a.id} className="check-row"><input type="checkbox" checked={selection.includes(String(a.id))} disabled={sale&&(a.reservada===true||a.estado!=='DISPONIBLE')} onChange={e=>setSelection(current=>e.target.checked?[...current,String(a.id)]:current.filter(x=>x!==a.id))}/><span><strong>{text(a.codigo||a.identificador||a.animal_id||a.id)}</strong><small>{text(a.estado||a.situacion)}{sale&&a.reservada===true?' · Reserva activa':''}</small></span>{sale&&<span className="numeric">{money(a.costo_vigente)}</span>}</label>)}</div></State><p>{selection.length} seleccionados</p><div className="form-grid"><FormField name="unidad_precio" label="Unidad de precio" initial={String(lot.unidad_precio||'CABEZA')} options={[{value:'CABEZA',label:'MXN por cabeza'},{value:'KG',label:'MXN por kg'}]}/><FormField name="precio_unitario" label="Precio unitario en MXN" initial={String(lot.precio_unitario||'')} help="Hasta cuatro decimales. El importe final lo calcula el servidor."/><FormField name="pesaje_base_id" label="Identificador del pesaje aprobado" initial={String(lot.pesaje_base_id||'')} required={false} help="Obligatorio al pactar precio por kg."/><FormField name="deduccion_pct" label="Deducción pactada en %" initial={String(lot.deduccion_pct||'')} required={false} help="Condición explícita del acuerdo; hasta seis decimales."/><FormField name="cargos_pactados" label="Cargos pactados en MXN" initial={inputDecimal(lot.cargos_pactados)} required={false}/><FormField name="bonificaciones_pactadas" label="Bonificaciones pactadas en MXN" initial={inputDecimal(lot.bonificaciones_pactadas)} required={false}/></div>{!sale&&<label className="check-row"><input type="checkbox" name="requiere_recepcion" defaultChecked={operation.requiere_recepcion===true||((operation.contratos as Row[])||[]).some(c=>c.numero_version===operation.numero_version_actual&&c.requiere_recepcion===true)}/> Compra pendiente de recepción física</label>}</CommandForm></>;
}
export function Settlement({base,sede,id,go}:{base:string;sede:Sede;id:string;go:(next:string,row?:Row)=>void}){
    const [rev,setRev]=useState(0);const r=useResource<Row>(base+'/liquidaciones/'+id,rev);const caja=sede.roles.some(x=>['ADMIN','CAJA'].includes(x));return <><section className="panel"><State {...r}>{r.data&&<><div className="section-heading"><div><p className="eyebrow">{text(r.data.direccion)}</p><h2>{r.data.folio||r.data.contraparte?'Liquidación '+text(r.data.folio||r.data.contraparte):r.data.direccion==='POR_COBRAR'?'Liquidación por cobrar':'Liquidación por pagar'}</h2><small className="uuid">{id}</small></div><button className="secondary" onClick={r.reload}>Actualizar saldo</button></div><div className="settlement-summary"><div><span>Saldo pendiente</span><strong><Amount value={r.data.saldo}/></strong><small>Vencimiento: {text(r.data.vence_el)}</small></div>{caja&&<button className="primary" onClick={()=>go('pagos',r.data)}>Registrar {r.data.direccion==='POR_COBRAR'?'cobro':'pago'}</button>}</div><dl className="facts"><div><dt>Operación económica</dt><dd>CONFIRMADA</dd></div><div><dt>Entrega física</dt><dd>{text(r.data.estado_entrega)}</dd></div><div><dt>Contraparte</dt><dd>{text(r.data.contraparte)}</dd></div></dl><div className="split-even"><div><h3>Desglose del cierre</h3><DataTable rows={r.data.conceptos as Row[]||[]} columns={[{key:'tipo',label:'Concepto'},{key:'cantidad',label:'Cantidad',numeric:true},{key:'unidad',label:'Unidad'},{key:'precio_unitario',label:'Precio',numeric:true},{key:'importe',label:'Importe',money:true}]}/></div><div><h3>Conciliación del saldo</h3><dl className="financial-breakdown">{[['total','Total original'],['ajustes_cargo','Cargos'],['ajustes_abono','Abonos'],['aplicaciones_netas','Aplicaciones netas'],['saldo','Saldo pendiente']].map(([key,label])=><div key={key}><dt>{label}</dt><dd>{money(r.data?.[key])}</dd></div>)}</dl></div></div><FinancialHistory base={base} data={r.data} caja={caja} onDone={()=>setRev(n=>n+1)}/><a className="text-button" href={'/api/v1'+base+'/liquidaciones/'+id+'/comprobante'} target="_blank" rel="noreferrer">Comprobante interno · no es CFDI ↗</a></>}</State></section>{sede.roles.includes('ADMIN')&&<section className="panel"><h2>Registrar ajuste</h2><p className="muted">Preserva el original y registra el motivo de la corrección.</p><CommandForm path={base+'/liquidaciones/'+id+'/ajustes'} label="Registrar ajuste" build={f=>({...recognition(f),naturaleza:str(f,'naturaleza'),monto:cash(f),motivo:str(f,'motivo'),fuente:str(f,'fuente'),reaplicar_pagos:f.has('reaplicar_pagos')})} onDone={()=>setRev(n=>n+1)}><div className="form-grid"><FormField name="naturaleza" label="Naturaleza" options={['CARGO','ABONO'].map(x=>({value:x,label:text(x)}))}/><FormField name="importe" label="Importe del ajuste en MXN"/><FormField name="motivo" label="Motivo"/><PeriodFields base={base}/><FormField name="fuente" label="Origen del ajuste" options={['PRECIO_GANADO','BONIFICACION_COMERCIAL','OTRO'].map(x=>({value:x,label:text(x)}))}/></div><label className="check-row"><input type="checkbox" name="reaplicar_pagos"/> Conciliar ajuste y aplicaciones en una sola operación</label><p className="muted">Cuando el abono reduce una obligación ya pagada, el servidor conserva originales, registra reversos y reaplica dentro de la misma transacción. El excedente queda disponible para reembolso.</p></CommandForm></section>}</>;
}
export function Payments({base,sede,context}:{base:string;sede:Sede;context?:Row}){
    const [rev,setRev]=useState(0);const [selected,setSelected]=useState<Row>();const [refreshError,setRefreshError]=useState<Error>();const [destination,setDestination]=useState<Row|undefined>(context);const [query,setQuery]=useState(String(context?.id||''));const [search,setSearch]=useState(String(context?.id||''));const [page,setPage]=useState(1);const list=useResource<Page>(base+'/liquidaciones?'+new URLSearchParams({pagina:String(page),tamano:'20',...(search?{q:search}:{})}),rev);const caja=sede.roles.some(x=>['ADMIN','CAJA'].includes(x));const refreshPayment=(id:string)=>{setRefreshError(undefined);request<Row>(base+'/pagos/'+id).then(result=>setSelected(result.data)).catch(e=>setRefreshError(e as Error));setRev(n=>n+1);};const bump=()=>{if(selected?.id)refreshPayment(String(selected.id));else setRev(n=>n+1);};
    const compatible=list.data?.elementos.filter(l=>l.saldo&&typeof l.saldo==='object'&&'importe' in l.saldo&&!/^[-]|^0+(?:\.0+)?$/.test(String(l.saldo.importe))&&(!selected||(l.parte_id===selected.parte_id&&((l.direccion==='POR_COBRAR'&&selected.tipo==='COBRO')||(l.direccion==='POR_PAGAR'&&selected.tipo==='PAGO')))))||[];
    return <><Notice error={refreshError}/><div className="split"><section className="panel"><h2>Dinero registrado</h2><List path={base+'/pagos'} filters={[{name:'estado',label:'Estado del pago',options:['REGISTRADO','VALIDADO']},{name:'tipo',label:'Dirección',options:['COBRO','PAGO']}]} revision={rev} columns={[{key:'id',label:'Registro de pago'},{key:'tipo',label:'Dirección'},{key:'estado',label:'Estado'},{key:'importe',label:'Importe',money:true},{key:'disponible',label:'Disponible',money:true}]} onSelect={setSelected}/></section>{caja&&<section className="panel"><h2>Registrar {context?.direccion==='POR_PAGAR'?'pago':'cobro o pago'}</h2><p className="muted">Registrar dinero no salda una obligación: después debes validarlo y aplicarlo.</p><CommandForm path={base+'/pagos'} label="Registrar dinero" build={f=>({parte_id:str(f,'parte_id'),tipo:str(f,'tipo'),importe:cash(f),metodo:str(f,'metodo'),referencia:str(f,'referencia'),recibido_el:str(f,'recibido_el')})} onDone={data=>refreshPayment(String(data.id))}><PartyField base={base} initial={String(context?.parte_id||'')}/><div className="form-grid"><FormField name="tipo" label="Dirección del dinero" initial={context?.direccion==='POR_PAGAR'?'PAGO':'COBRO'} options={[{value:'COBRO',label:'Cobro recibido'},{value:'PAGO',label:'Pago entregado'}]}/><FormField name="importe" label="Importe en MXN"/><FormField name="metodo" label="Método" options={['TRANSFERENCIA','EFECTIVO','CHEQUE','OTRO'].map(x=>({value:x,label:text(x)}))}/><FormField name="recibido_el" label="Fecha" type="date" initial={today()}/></div><FormField name="referencia" label="Referencia" required={false}/></CommandForm></section>}</div>{selected&&<section className="panel"><div className="section-heading"><h2>Disponible de {text(selected.tipo).toLowerCase()}</h2><span className="badge">{text(selected.estado)}</span></div><div className="settlement-summary"><div><span>Saldo a favor / anticipo</span><strong><Amount value={selected.disponible}/></strong><small>{text(selected.id)}</small></div></div>{caja&&selected.estado==='REGISTRADO'&&<CommandForm path={base+'/pagos/'+selected.id+'/validar'} label="Validar pago revisado" build={recognition} onDone={bump}><div className="form-grid"><PeriodFields base={base}/></div></CommandForm>}{caja&&selected.estado==='VALIDADO'&&<><h3>Aplicar a una obligación compatible</h3><div className="list-filters"><Field name="buscar_liquidacion" label="Buscar obligación por identificador o contraparte" required={false} value={query} onChange={setQuery}/><button type="button" className="secondary" onClick={()=>{setSearch(query.trim());setPage(1);}}>Buscar obligación</button></div><State {...list} empty={!compatible.length}><DataTable rows={compatible} columns={[{key:'id',label:'Liquidación'},{key:'direccion',label:'Dirección'},{key:'saldo',label:'Saldo pendiente',money:true}]} onSelect={setDestination}/></State>{list.data&&<div className="pagination"><span>{list.data.total} obligaciones consultadas · Página {page}</span><div><button className="secondary" disabled={page===1} onClick={()=>setPage(p=>p-1)}>Anterior</button><button className="secondary" disabled={page*20>=list.data!.total} onClick={()=>setPage(p=>p+1)}>Siguiente</button></div></div>}{destination&&compatible.some(l=>l.id===destination.id)&&<CommandForm key={String(destination.id)} path={base+'/pagos/'+selected.id+'/aplicaciones'} label="Aplicar pago a liquidación" build={f=>({...recognition(f),aplicaciones:[{liquidacion_id:destination.id,importe:cash(f)}]})} onDone={bump}><p>Destino: <strong>{text(destination.id)}</strong> · saldo {money(destination.saldo)}</p><FormField name="importe" label="Importe a aplicar en MXN"/><div className="form-grid"><PeriodFields base={base}/></div></CommandForm>}<RefundForm base={base} payment={selected} onDone={bump}/></>}</section>}</>;
}
export function Report({base,kind,go}:{base:string;kind:'cartera'|'margen';go:(next:string,row?:Row)=>void}){
    const [page,setPage]=useState(1);const [query,setQuery]=useState('');const [search,setSearch]=useState('');const [overdue,setOverdue]=useState('');const qs=kind==='cartera'?'?'+new URLSearchParams({pagina:String(page),tamano:'20',...(search?{q:search}:{}),...(overdue?{vencida:overdue}:{})}):'';const r=useResource<Row>(base+'/reportes/'+kind+qs);
    return <section className="panel">{kind==='cartera'&&<form className="list-filters" aria-label="Buscar obligaciones" onSubmit={e=>{e.preventDefault();setSearch(query.trim());setPage(1);}}><Field name="q" label="Buscar en cartera" type="search" required={false} value={query} onChange={setQuery}/><Field name="vencida" label="Vencimiento" required={false} value={overdue} onChange={value=>{setOverdue(value);setPage(1);}} options={[{value:'true',label:'Sólo vencidas'},{value:'false',label:'No vencidas'}]}/><button className="secondary">Buscar</button></form>}<State {...r}>{r.data&&<><div className="section-heading"><h2>{kind==='cartera'?'Obligaciones pendientes':'Resultado económico'}</h2><div className="actions"><a className="text-button" href={'/api/v1'+base+'/reportes/'+kind+'/csv'}>Exportar CSV de toda la sede</a><button className="secondary" onClick={r.reload}>Actualizar consulta</button></div></div><p className="meta-line"><span>Corte: <time dateTime={String(r.data.corte_en||'')}>{when(r.data.corte_en)}</time></span>{r.data.etiqueta?<span className="badge" data-tone={toneOf(r.data.etiqueta)}>{text(r.data.etiqueta)}</span>:<span>Consolidación no informada</span>}<span>Fuente: {r.data.fuente_consulta?text(r.data.fuente_consulta):'No informada'}</span></p>{typeof r.data.antiguedad_replica_segundos==='number'?r.data.antiguedad_replica_segundos>0&&<p className="notice">Datos de réplica con antigüedad de {r.data.antiguedad_replica_segundos} segundos.</p>:<p className="notice">La antigüedad de la réplica no está informada. El corte identifica esta consulta.</p>}{kind==='cartera'?<><DataTable rows={r.data.filas as Row[]||[]} columns={[{key:'liquidacion_id',label:'Liquidación'},{key:'contraparte',label:'Contraparte'},{key:'saldo',label:'Saldo',money:true},{key:'vence_el',label:'Vencimiento'},{key:'dias_vencida',label:'Días vencida'}]} onSelect={x=>go('liquidaciones',{id:String(x.liquidacion_id)})}/>{!((r.data.filas as Row[])||[]).length&&<p className="notice">No hay obligaciones con estos criterios.</p>}<div className="pagination"><span>{text(r.data.total)} registros · Página {page}</span><div><button className="secondary" disabled={page===1} onClick={()=>setPage(p=>p-1)}>Anterior</button><button className="secondary" disabled={page*20>=Number(r.data.total)} onClick={()=>setPage(p=>p+1)}>Siguiente</button></div></div></>:<div className="metric-grid five">{[['venta_neta','Venta neta'],['costo_vendido','Costo vendido'],['gastos_directos','Gastos directos'],['margen','Margen'],['perdidas','Pérdidas']].map(([k,label])=><div className={k==='margen'?'metric hero':'metric'} key={k}><span>{label}</span><strong><Amount value={r.data?.[k]}/></strong></div>)}</div>}</>}</State></section>;
}

export function Documents({base,sede}:{base:string;sede:Sede}){const [rev,setRev]=useState(0);const [selected,setSelected]=useState<Row>();const operator=sede.roles.some(x=>['ADMIN','OPERADOR'].includes(x));return <><div className="split"><section className="panel"><h2>Documentos privados</h2><List path={base+'/documentos'} revision={rev} columns={[{key:'id',label:'Documento'},{key:'tipo_documental',label:'Tipo'},{key:'mime',label:'Formato'},{key:'version',label:'Versión'}]} onSelect={setSelected}/></section>{operator&&<section className="panel"><h2>Agregar evidencia</h2><DocumentUpload base={base} onDone={()=>setRev(n=>n+1)}/></section>}</div>{selected&&<DocumentDetail key={String(selected.id)} base={base} sede={sede} id={String(selected.id)}/>}</>;}
function DocumentDetail({base,sede,id}:{base:string;sede:Sede;id:string}){const [rev,setRev]=useState(0);const r=useResource<Row>(base+'/documentos/'+id,rev);return <section className="panel"><h2>Versión documental y revisión</h2><State {...r}>{r.data&&<><dl className="facts"><div><dt>Tipo</dt><dd>{text(r.data.tipo_documental)}</dd></div><div><dt>Versión</dt><dd>{text(r.data.version)}</dd></div><div><dt>Formato</dt><dd>{text(r.data.mime)}</dd></div><div><dt>Contenido sintético</dt><dd>{text(r.data.es_sintetico)}</dd></div></dl><a className="text-button" href={'/api/v1'+base+'/documentos/'+id+'/contenido'}>Descargar esta versión autorizada</a><DataTable rows={r.data.revisiones as Row[]||[]} columns={[{key:'revision_id',label:'Revisión'},{key:'resultado',label:'Resultado'},{key:'observacion',label:'Observación'}]}/></>}</State>{sede.roles.includes('ADMIN')&&<CommandForm path={base+'/documentos/'+id+'/revisiones'} label="Registrar revisión administrativa" build={f=>({operacion_id:str(f,'operacion_id'),criterio:str(f,'criterio'),resultado:str(f,'resultado'),documentos:[{documento_id:id,resultado:str(f,'resultado'),observacion:str(f,'observacion')||undefined}]})} onDone={()=>setRev(n=>n+1)}><FormField name="operacion_id" label="Operación revisada"/><FormField name="criterio" label="Criterio de revisión"/><FormField name="resultado" label="Resultado de revisión" options={['SIN_OBSERVACIONES','CON_OBSERVACIONES','RECHAZADA'].map(x=>({value:x,label:text(x)}))}/><FormField name="observacion" label="Observación" required={false}/></CommandForm>}</section>;}

function DocumentUpload({base,onDone}:{base:string;onDone:()=>void}){
    const path=base+'/documentos';const [attempt,setAttempt]=useState<Attempt|undefined>(()=>readPending(path));const [busy,setBusy]=useState(false);const [error,setError]=useState<Error>();const [success,setSuccess]=useState(false);const upload=useRef<FormData|undefined>(undefined);
    async function submit(form:HTMLFormElement){setBusy(true);setError(undefined);setSuccess(false);try{
        let data=upload.current;let command=attempt;
        if(command){const prior=await commandResult<Row>(command);if(prior.completed){forgetPending(path);setAttempt(undefined);upload.current=undefined;setSuccess(true);onDone();return;}}
        if(!data){data=new FormData(form);const file=data.get('archivo');if(!(file instanceof File)||!file.size)throw new Error('Selecciona un archivo.');if(file.size>20*1024*1024)throw new Error('El archivo supera 20 MiB.');if(!['application/pdf','image/jpeg','image/png'].includes(file.type))throw new Error('Selecciona un PDF, JPEG o PNG.');
            const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer())),b=>b.toString(16).padStart(2,'0')).join('');
            const fingerprint={nombre:file.name,tamano:file.size,sha256:hash,tipo_documental:String(data.get('tipo_documental')),operacion_id:String(data.get('operacion_id')||'')};
            if(command&&command.body!==JSON.stringify(fingerprint))throw new Error('Este intento está pendiente. Selecciona el mismo archivo y tipo documental para reintentar.');
            if(!command){command=createAttempt(path,fingerprint);rememberPending(command);setAttempt(command);}upload.current=data;
        }
        await request(path,{method:'POST',body:data,headers:{'Idempotency-Key':command!.key}});forgetPending(path);setAttempt(undefined);upload.current=undefined;setSuccess(true);onDone();
    }catch(e){const err=e as Error;setError(err);if(!keepAttempt(err)){forgetPending(path);setAttempt(undefined);upload.current=undefined;}}finally{setBusy(false);}}
    return <form className="command" onSubmit={e=>{e.preventDefault();void submit(e.currentTarget);}}><Notice error={error}/>{attempt&&<p className="notice">Conservamos el intento de subida. Si recargaste, selecciona el mismo archivo y tipo; su huella debe coincidir. Se reutiliza la clave original.</p>}<fieldset disabled={busy||!!upload.current}><FormField name="tipo_documental" label="Tipo documental" options={['TICKET_BASCULA','CONTRATO','GUIA_MOVILIZACION','COMPROBANTE_PAGO','IDENTIFICACION','OTRO'].map(x=>({value:x,label:text(x)}))}/><FormField name="operacion_id" label="Vincular a una operación" required={false} help="Opcional: copia el identificador del expediente."/><label className="field">Archivo PDF, JPEG o PNG · máximo 20 MiB<input type="file" name="archivo" accept="application/pdf,image/jpeg,image/png" required={!attempt}/></label></fieldset>{success&&<p className="notice success" role="status">Documento guardado por el servidor.</p>}<button className="primary" disabled={busy}>{busy?'Subiendo…':attempt?'Reintentar el mismo documento':'Guardar documento'}</button></form>;
}
export function TicketHistory({base,id,sede}:{base:string;id:string;sede:Sede}){
    const [rev,setRev]=useState(0);const [selected,setSelected]=useState<Row>();const r=useResource<Page|Row[]>(base+'/operaciones/'+id+'/pesajes',rev);const rows=Array.isArray(r.data)?r.data:r.data?.elementos||[];const operator=sede.roles.some(role=>['ADMIN','OPERADOR'].includes(role));
    return <section className="panel"><h2>Tickets y composición animal</h2><p className="muted">Cada peso conserva su composición. Una variación entre tickets no constituye una deducción pactada.</p><State {...r} empty={!rows.length}><DataTable rows={rows.map(ticket=>({...ticket,composicion:((ticket.animales as Row[])||[]).map(animal=>text(animal.animal_id)+' · '+(animal.peso_individual?text(animal.peso_individual):'Sin medición individual')).join(' | ')}))} columns={[{key:'ticket_folio',label:'Ticket'},{key:'neto',label:'Peso neto'},{key:'estado',label:'Revisión'},{key:'composicion',label:'Composición'},{key:'corrige_a_id',label:'Corrige al ticket'},{key:'motivo_correccion',label:'Motivo de corrección'},{key:'pesado_en',label:'Fecha de pesaje'}]} onSelect={operator?setSelected:undefined}/></State><TicketComparison base={base} tickets={rows}/>{operator&&selected&&<TicketCorrection key={String(selected.id)} base={base} ticket={selected} onDone={result=>{setSelected(result);setRev(value=>value+1);}}/>}</section>;
}
function TicketCorrection({base,ticket,onDone}:{base:string;ticket:Row;onDone:(result:Row)=>void}){
    const animals=(Array.isArray(ticket.animales)?ticket.animales:[]) as Row[];
    if(ticket.estado==='PROPUESTA')return <div className="subpanel"><h3>Propuesta por revisar · {text(ticket.id)}</h3><CommandForm path={base+'/pesajes/'+ticket.id+'/aprobar'} label="Aprobar corrección revisada" build={()=>({})} onDone={onDone}><p>Verifica el nuevo ticket y sus animales antes de aprobar. El ticket anterior permanece en el historial.</p></CommandForm></div>;
    if(ticket.estado!=='APROBADO')return <p className="notice">Este ticket conserva su historia; selecciona una versión aprobada para corregir.</p>;
    if(!animals.length||animals.some(animal=>!animal.animal_id))return <p className="notice">El servidor no entregó la composición original. Recarga el historial antes de corregir; no se sustituirá por la composición del lote actual.</p>;
    return <div className="subpanel"><h3>Corregir ticket aprobado · {text(ticket.id)}</h3><p>La corrección crea una propuesta nueva vinculada a esta versión exacta. Conserva el peso y los animales originales; registra el motivo.</p><CommandForm path={base+'/pesajes/'+ticket.id+'/correcciones'} label="Registrar corrección de pesaje" build={f=>({numero_lote: Number(ticket.numero_lote),modo:'NETO_REPORTADO',neto:{kg:canonicalDecimal(str(f,'neto'),3)},pesado_en:new Date(str(f,'pesado_en')).toISOString(),ticket_folio:str(f,'ticket_folio'),documento_id:str(f,'documento_id')||undefined,motivo:str(f,'motivo'),corrige_a_id:String(ticket.id),animales:animals.map(animal=>({animal_id:String(animal.animal_id),...(str(f,'peso_'+animal.animal_id)?{peso_individual:{kg:canonicalDecimal(str(f,'peso_'+animal.animal_id),3)}}:{})}))} satisfies components['schemas']['PesajeNuevo'] & {motivo:string;corrige_a_id:string})} onDone={onDone}><div className="form-grid"><FormField name="neto" label="Nuevo peso neto en kg"/><FormField name="ticket_folio" label="Folio de la corrección"/><FormField name="pesado_en" label="Fecha y hora de la corrección" type="datetime-local"/><FormField name="motivo" label="Motivo de corrección" help="Describe el motivo en 1–200 caracteres."/><FormField name="documento_id" label="Documento de evidencia" required={false}/>{animals.map(animal=><FormField key={String(animal.animal_id)} name={'peso_'+animal.animal_id} label={'Peso corregido en kg · '+animal.animal_id} required={false}/>)}</div></CommandForm></div>;
}
export function CaseFile({base,id}:{base:string;id:string}){
    const r=useResource<Row>(base+'/operaciones/'+id+'/expediente');const events=(r.data?.eventos||r.data?.hechos||[]) as Row[];const documents=(r.data?.documentos||[]) as Row[];
    return <section className="panel"><div className="section-heading"><h2>Historia del expediente</h2><button className="secondary" onClick={r.reload}>Actualizar hechos</button></div><State {...r}>{events.length?<ol className="timeline">{events.map((event,i)=><li key={String(event.id||i)}><p className="eyebrow">{text(event.ocurrido_en||event.fecha||event.creado_en)}</p><h3>{text(event.tipo||event.accion)}</h3><p>{text(event.descripcion||event.estado)}</p></li>)}</ol>:<p className="notice">La consulta no contiene eventos para este expediente.</p>}<h3>Evidencia conservada</h3>{documents.length?<ul className="document-links">{documents.map(d=><li key={String(d.id)}><a href={'/api/v1'+base+'/documentos/'+d.id+'/contenido'}>{text(d.tipo_documental)} · versión {text(d.version)} · {text(d.mime)}</a></li>)}</ul>:<p className="muted">No hay documentos vinculados.</p>}</State></section>;
}
export function ControlView({base,kind}:{base:string;kind:'usuarios'|'sincronizacion'}){const r=useResource<Page|Row>(base+'/'+kind);return <section className="panel"><div className="section-heading"><h2>{kind==='usuarios'?'Accesos de la sede':'Estado de sincronización'}</h2><button className="secondary" onClick={r.reload}>Actualizar consulta</button></div><State {...r}>{kind==='usuarios'?<DataTable rows={(r.data as Page)?.elementos||[]} columns={[{key:'nombre',label:'Nombre'},{key:'login',label:'Usuario'},{key:'roles',label:'Roles'},{key:'activo',label:'Vigencia'}]}/>:<><dl className="facts"><div><dt>Estado</dt><dd>{text((r.data as Row)?.estado)}</dd></div><div><dt>Última actualización</dt><dd>{text((r.data as Row)?.ultima_sincronizacion)}</dd></div></dl>{(r.data as Row)?.avisos&&<p className="notice">{text((r.data as Row).avisos)}</p>}</>}</State></section>;}
export function Simulator({base,id}:{base:string;id:string}){const r=useResource<Row>(base+'/operaciones/'+id+'/simulador');return <section className="panel"><div className="section-heading"><h2>Simulación del borrador</h2><span className="badge">No registra hechos</span></div><State {...r}>{r.data&&<><div className="settlement-summary"><div><span>Total calculado por el servidor</span><strong><Amount value={r.data.total}/></strong></div></div><DataTable rows={r.data.conceptos as Row[]||[]} columns={[{key:'tipo',label:'Concepto'},{key:'cantidad',label:'Cantidad'},{key:'unidad',label:'Unidad'},{key:'precio_unitario',label:'Precio'},{key:'importe',label:'Importe',money:true}]}/>{r.data.faltantes&&<p className="notice">Faltantes: {text(r.data.faltantes)}</p>}</>}</State></section>;}

export function MovementCapture({base,sede}:{base:string;sede:Sede}){const [type,setType]=useState('RECEPCION');return <section className="panel narrow"><h2>Recepción, entrega o baja</h2><CommandForm path={base+'/inventario/movimientos'} label="Registrar movimiento físico" build={f=>({tipo:type,posiciones:str(f,'posiciones').split(/[\s,]+/).filter(Boolean),operacion_id:str(f,'operacion_id')||undefined,ocurrido_en:new Date(str(f,'ocurrido_en')).toISOString(),motivo_baja:str(f,'motivo_baja')||undefined,documento_id:str(f,'documento_id')||undefined,...(type==='BAJA'?recognition(f):{})})}><Field name="tipo" label="Movimiento" value={type} onChange={setType} options={['RECEPCION','ENTREGA',...(sede.roles.includes('ADMIN')?['BAJA']:[])].map(x=>({value:x,label:text(x)}))}/><FormField name="posiciones" label="Identificadores de posiciones" help="Copia los identificadores del inventario, separados por coma."/>{type==='ENTREGA'&&<FormField name="operacion_id" label="Identificador de la venta confirmada"/>}<FormField name="ocurrido_en" label="Fecha y hora" type="datetime-local"/>{type==='BAJA'&&<><FormField name="motivo_baja" label="Motivo de baja" options={['PERDIDA','MUERTE'].map(x=>({value:x,label:text(x)}))}/><FormField name="documento_id" label="Documento de evidencia"/><div className="form-grid"><PeriodFields base={base}/></div></>}</CommandForm></section>;}
export function ExpenseDetail({base,sede,id}:{base:string;sede:Sede;id:string}){
    const [rev,setRev]=useState(0);const [method,setMethod]=useState('POR_CABEZA');const r=useResource<Row>(base+'/gastos/'+id+'/reparto?metodo='+(method==='IMPORTE_INDIVIDUAL'?'POR_CABEZA':method),rev);const allocations=(r.data?.asignaciones||r.data?.elementos||[]) as Row[];
    return <section className="panel"><h2>Previsualizar y repartir gasto</h2><p className="muted">Los destinos, bases e importes de la previsualización se calculan en el servidor. Aprobar registra las asignaciones.</p><Field name="metodo" label="Método de reparto" value={method} onChange={setMethod} options={['POR_CABEZA','POR_PESO_MEDIDO','IMPORTE_INDIVIDUAL'].map(x=>({value:x,label:text(x)}))}/><State {...r}>{allocations.length?<DataTable rows={allocations} columns={method==='IMPORTE_INDIVIDUAL'?[{key:'posicion_id',label:'Posición a asignar'}]:[{key:'posicion_id',label:'Posición'},{key:'base_valor',label:'Base del reparto'},{key:'importe',label:'Importe asignado',money:true},{key:'destino',label:'Destino del costo'}]}/>:<p className="notice">No hay destinos disponibles para la previsualización de este gasto.</p>}</State>{sede.roles.some(x=>['ADMIN','OPERADOR'].includes(x))&&<CommandForm key={method} path={base+'/gastos/'+id+'/reparto'} label="Aprobar reparto revisado" build={f=>{if(method==='IMPORTE_INDIVIDUAL'&&!allocations.length)throw new Error('Consulta los destinos del gasto antes de indicar importes individuales.');return {...recognition(f),metodo:method,...(method==='IMPORTE_INDIVIDUAL'?{asignaciones:allocations.map((a,i)=>({posicion_id:a.posicion_id,importe:cash(f,'asignacion_'+i)}))}:{})};}} onDone={()=>setRev(n=>n+1)}>{method==='IMPORTE_INDIVIDUAL'&&allocations.map((a,i)=><FormField key={String(a.posicion_id)} name={'asignacion_'+i} label={'Importe en MXN · '+text(a.posicion_id)}/>)}<div className="form-grid"><PeriodFields base={base}/></div></CommandForm>}</section>;
}
export function Periods({base,sede}:{base:string;sede:Sede}){const [rev,setRev]=useState(0);const [selected,setSelected]=useState<Row>();const admin=sede.roles.includes('ADMIN');return <><section className="panel"><h2>Periodos económicos</h2><List path={base+'/periodos'} revision={rev} columns={[{key:'fecha_inicio',label:'Desde'},{key:'fecha_fin',label:'Hasta'},{key:'estado',label:'Estado'}]} onSelect={setSelected}/>{selected&&admin&&<div className="subpanel"><h3>Periodo seleccionado · {text(selected.estado)}</h3><PeriodVersions base={base} id={String(selected.id)}/><CommandForm key={String(selected.id)+String(selected.estado)} path={base+'/periodos/'+selected.id+(selected.estado==='ABIERTO'?'/cierre':'/reabrir')} label={selected.estado==='ABIERTO'?'Cerrar periodo conciliado':'Reabrir periodo con motivo'} build={f=>({motivo:str(f,'motivo')})} onDone={()=>{setSelected(undefined);setRev(n=>n+1);}}><p>El servidor revisará el orden de periodos y registrará una nueva versión del cierre.</p><FormField name="motivo" label="Motivo de la acción"/></CommandForm></div>}</section>{admin&&<section className="panel narrow"><h2>Abrir un nuevo periodo</h2><p className="muted">Un mes calendario completo, consecutivo al anterior. Solo puede existir un periodo abierto por sede.</p><CommandForm path={base+'/periodos'} label="Crear periodo económico" build={f=>({fecha_inicio:str(f,'fecha_inicio'),fecha_fin:str(f,'fecha_fin')})} onDone={()=>setRev(n=>n+1)}><div className="form-grid"><FormField name="fecha_inicio" label="Primer día del mes" type="date"/><FormField name="fecha_fin" label="Último día del mes" type="date"/></div></CommandForm></section>}</>;}
export function ExpenseCapture({base,onDone}:{base:string;onDone:()=>void}){
    const [nature,setNature]=useState('COSTO');const [snapshot,setSnapshot]=useState<Row>();
    return <><ProviderTariffs base={base} onAccepted={setSnapshot}/><section className="panel"><h2>Registrar gasto o bonificación</h2><CommandForm path={base+'/gastos'} label="Registrar gasto" build={f=>({...recognition(f),operacion_id:str(f,'operacion_id'),naturaleza:nature,clasificacion:str(f,'clasificacion'),importe:snapshot?snapshot.precio:cash(f),snapshot_id:snapshot?.snapshot_id,concepto:str(f,'concepto'),fecha_economica:str(f,'fecha_economica'),proveedor_parte_id:str(f,'proveedor_parte_id')||undefined,referencia_origen:str(f,'referencia_origen')||undefined,bonifica_gasto_id:str(f,'bonifica_gasto_id')||undefined,documento_id:str(f,'documento_id')||undefined})} onDone={onDone}><FormField name="operacion_id" label="Identificador de operación"/><Field name="naturaleza" label="Naturaleza" value={nature} onChange={setNature} options={['COSTO','BONIFICACION'].map(x=>({value:x,label:text(x)}))}/>{nature==='BONIFICACION'&&<FormField name="bonifica_gasto_id" label="Gasto original que se bonifica" help="Conserva el original y enlaza esta bonificación con su gasto aprobado."/>}<FormField name="clasificacion" label="Clasificación" options={['CAPITALIZABLE','DIRECTO_VENTA','OTRO'].map(x=>({value:x,label:text(x)}))}/>{snapshot?<p className="notice">Tarifa aceptada: <strong>{money(snapshot.precio)}</strong> · {text(snapshot.ruta)} · versión {text(snapshot.version)}</p>:<FormField name="importe" label="Importe en MXN"/>}<FormField name="concepto" label="Concepto"/><PartyField base={base} name="proveedor_parte_id" label="Proveedor del gasto" required={false}/><FormField name="referencia_origen" label="Referencia de origen" required={false}/><FormField name="documento_id" label="Documento de evidencia" required={false}/><FormField name="fecha_economica" label="Fecha económica declarada" type="date" initial={today()}/><div className="form-grid"><PeriodFields base={base}/></div></CommandForm></section></>;
}
function ProviderTariffs({base,onAccepted}:{base:string;onAccepted:(row?:Row)=>void}){
    const path=base+'/integraciones/proveedor/tarifas/aceptaciones';const [selected,setSelected]=useState(()=>{const pending=readPending(path);try{return pending?.body?String(JSON.parse(pending.body).snapshot_id||''):'';}catch{return '';}});const tariffs=useResource<Page>(base+'/integraciones/proveedor/tarifas?pagina=1&tamano=100');const tariff=tariffs.data?.elementos.find(t=>t.snapshot_id===selected);const lookupError=tariffs.error instanceof ApiError&&[0,503].includes(tariffs.error.status)?new Error('La consulta de tarifas del proveedor no está disponible. Conserva tu captura y vuelve a consultar.'):tariffs.error;
    return <section className="panel"><h2>Tarifas de proveedor</h2><p className="muted">Elige una tarifa consultada y acepta su versión antes de asociarla al gasto. También puedes registrar un gasto sin tarifa.</p><State {...tariffs} error={lookupError} empty={!tariffs.data?.elementos.length}><CommandForm path={path} label="Aceptar tarifa para este gasto" build={()=>({snapshot_id:selected})} onDone={()=>{if(tariff)onAccepted(tariff);}}><Field name="snapshot_id" label="Tarifa consultada" value={selected} onChange={id=>{setSelected(id);onAccepted(undefined);}} options={tariffs.data?.elementos.map(t=>({value:String(t.snapshot_id),label:text(t.ruta)+' · '+money(t.precio)+' · versión '+text(t.version)}))||[]}/>{tariff&&<dl className="facts"><div><dt>Fuente</dt><dd>{text(tariff.fuente)}</dd></div><div><dt>Unidad</dt><dd>{text(tariff.unidad)}</dd></div><div><dt>Vigente desde</dt><dd>{text(tariff.vigente_desde)}</dd></div></dl>}</CommandForm></State></section>;
}
function PeriodVersions({base,id}:{base:string;id:string}){const r=useResource<Page|Row[]>(base+'/periodos/'+id+'/versiones');const rows=Array.isArray(r.data)?r.data:r.data?.elementos||[];return <><h3>Versiones inmutables del cierre</h3><State {...r} empty={!rows.length}><DataTable rows={rows} columns={[{key:'numero_version',label:'Versión'},{key:'tipo',label:'Hecho'},{key:'motivo',label:'Motivo'},{key:'corte_en',label:'Fecha'}]}/></State></>;}
function FinancialHistory({base,data,caja,onDone}:{base:string;data:Row;caja:boolean;onDone:()=>void}){const [selected,setSelected]=useState<Row>();const applications=(data.aplicaciones||[]) as Row[];const adjustments=(data.ajustes||[]) as Row[];return <><h3>Ajustes y correcciones</h3>{adjustments.length?<DataTable rows={adjustments} columns={[{key:'naturaleza',label:'Tipo'},{key:'monto',label:'Importe',money:true},{key:'motivo',label:'Motivo'}]}/>:<p className="muted">No hay ajustes registrados.</p>}<h3>Aplicaciones y reversos</h3>{applications.length?<DataTable rows={applications} columns={[{key:'pago_id',label:'Pago'},{key:'naturaleza',label:'Hecho'},{key:'importe',label:'Importe',money:true}]} onSelect={caja?setSelected:undefined}/>:<p className="muted">No hay aplicaciones registradas.</p>}{caja&&selected&&selected.naturaleza!=='REVERSO'&&<CommandForm key={String(selected.id)} path={base+'/aplicaciones/'+selected.id+'/reverso'} label="Revertir aplicación con motivo" build={f=>({...recognition(f),motivo:str(f,'motivo')})} onDone={onDone}><p>La aplicación original permanece en el historial. El reverso recupera disponible en su pago.</p><FormField name="motivo" label="Motivo del reverso"/><div className="form-grid"><PeriodFields base={base}/></div></CommandForm>}</>;}
function RefundForm({base,payment,onDone}:{base:string;payment:Row;onDone:(data:Row)=>void}){return <div className="subpanel"><h3>Reembolsar disponible</h3><p className="muted">El reembolso conserva el pago original y registra la salida de dinero disponible.</p><CommandForm path={base+'/pagos/'+payment.id+'/reembolsos'} label="Registrar reembolso" build={f=>({...recognition(f),importe:cash(f),metodo:str(f,'metodo'),referencia:str(f,'referencia'),recibido_el:str(f,'recibido_el')})} onDone={onDone}><div className="form-grid"><FormField name="importe" label="Importe a reembolsar en MXN"/><FormField name="metodo" label="Método del reembolso" options={['TRANSFERENCIA','EFECTIVO','CHEQUE','OTRO'].map(x=>({value:x,label:text(x)}))}/><FormField name="recibido_el" label="Fecha de entrega" type="date" initial={today()}/><FormField name="referencia" label="Referencia del reembolso" required={false}/><PeriodFields base={base}/></div></CommandForm></div>;}
export function Users({base,sede}:{base:string;sede:Sede}){const [rev,setRev]=useState(0);const [selected,setSelected]=useState<Row>();const admin=sede.roles.includes('ADMIN');return <><section className="panel"><h2>Acceso por sede</h2><List path={base+'/usuarios'} revision={rev} columns={[{key:'nombre',label:'Nombre'},{key:'login',label:'Usuario'},{key:'roles',label:'Roles'},{key:'estado',label:'Estado'}]} onSelect={admin?setSelected:undefined}/></section>{admin&&<div className="split"><section className="panel"><h2>Crear usuario</h2><SensitiveUserCreate base={base} onDone={data=>{setSelected(data);setRev(n=>n+1);}}/></section>{selected&&<section className="panel"><h2>Administrar acceso · {text(selected.nombre)}</h2><CommandForm key={String(selected.id)} path={base+'/usuarios/'+selected.id} method="PATCH" label="Guardar estado del usuario" build={f=>({nombre:str(f,'nombre'),estado:str(f,'estado')})} onDone={()=>setRev(n=>n+1)}><FormField name="nombre" label="Nombre del usuario" initial={String(selected.nombre||'')}/><FormField name="estado" label="Estado de acceso" initial={String(selected.estado||'ACTIVO')} options={['ACTIVO','BLOQUEADO'].map(x=>({value:x,label:text(x)}))}/></CommandForm><h3>Rol en esta sede</h3><CommandForm path={base+'/usuarios/'+selected.id+'/membresias'} label="Guardar permiso por sede" build={f=>({rol_codigo:str(f,'rol_codigo'),vigente:str(f,'vigente')==='true'})} onDone={()=>setRev(n=>n+1)}><FormField name="rol_codigo" label="Rol del producto" options={['ADMIN','OPERADOR','CAJA','AUDITOR'].map(x=>({value:x,label:text(x)}))}/><FormField name="vigente" label="Vigencia de este rol" initial="true" options={[{value:'true',label:'Autorizar acceso'},{value:'false',label:'Retirar acceso'}]}/></CommandForm></section>}</div>}</>;}
function SensitiveUserCreate({base,onDone}:{base:string;onDone:(data:Row)=>void}){
    const path=base+'/usuarios';const [attempt,setAttempt]=useState<Attempt|undefined>(()=>readPending(path));const body=useRef<string|undefined>(undefined);const [busy,setBusy]=useState(false);const [error,setError]=useState<Error>();const [success,setSuccess]=useState(false);
    async function submit(form:HTMLFormElement){setBusy(true);setError(undefined);setSuccess(false);try{let command=attempt;if(command){const result=await commandResult<Row>(command);if(result.completed){forgetPending(path);setAttempt(undefined);body.current=undefined;setSuccess(true);onDone(result.data as Row);return;}}
        if(!body.current){const fields=new FormData(form);const original=JSON.stringify({login:str(fields,'login'),nombre:str(fields,'nombre'),contrasena:str(fields,'contrasena')});if(!str(fields,'contrasena'))throw new Error('Escribe la contraseña del nuevo usuario.');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(original));const fingerprint={sha256:Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('')};if(command&&command.body!==JSON.stringify(fingerprint))throw new Error('El intento está pendiente. Usa el mismo usuario, nombre y contraseña para conservar su clave.');if(!command){command=createAttempt(path,fingerprint);rememberPending(command);setAttempt(command);}body.current=original;}
        const created=await request<Row>(path,{method:'POST',body:body.current,headers:{'Idempotency-Key':command!.key}});const name=JSON.parse(body.current).nombre;forgetPending(path);setAttempt(undefined);body.current=undefined;setSuccess(true);onDone({...created.data,nombre:name,estado:'ACTIVO'});form.reset();
    }catch(e){const err=e as Error;setError(err);if(!keepAttempt(err)){forgetPending(path);setAttempt(undefined);body.current=undefined;}}finally{setBusy(false);}}
    return <form className="command" onSubmit={e=>{e.preventDefault();void submit(e.currentTarget);}}><Notice error={error}/>{attempt&&<p className="notice">El intento conserva solo su clave y una huella del contenido. La contraseña permanece en memoria; después de recargar, ingresa los mismos datos para reintentar.</p>}<fieldset disabled={busy||!!body.current}><FormField name="login" label="Usuario de acceso" required={!attempt}/><FormField name="nombre" label="Nombre" required={!attempt}/><label className="field" htmlFor="new-user-password">Contraseña inicial *<input id="new-user-password" name="contrasena" type="password" autoComplete="new-password" required={!attempt}/></label></fieldset>{success&&<p className="notice success" role="status">Usuario creado. Selecciónalo para asignar un rol vigente en esta sede.</p>}<button className="primary" disabled={busy}>{busy?'Esperando respuesta…':attempt?'Consultar / reintentar el mismo usuario':'Crear usuario'}</button></form>;
}

function TicketComparison({base,tickets}:{base:string;tickets:Row[]}){const [first,setFirst]=useState('');const [last,setLast]=useState('');const options=tickets.map(t=>({value:String(t.id),label:text(t.ticket_folio||t.id)+' · '+text(t.neto)}));return <><h3>Comparar dos tickets</h3><div className="form-grid"><Field name="comparacion-inicial" label="Ticket inicial" value={first} onChange={setFirst} options={options}/><Field name="comparacion-final" label="Ticket final" value={last} onChange={setLast} options={options}/></div>{first&&last&&<ComparisonResult base={base} first={first} last={last}/>}</>;}
function ComparisonResult({base,first,last}:{base:string;first:string;last:string}){const r=useResource<Row>(base+'/pesajes/comparacion?inicial_id='+encodeURIComponent(first)+'&final_id='+encodeURIComponent(last));return <State {...r}>{r.data?.estado==='NO_COMPARABLE'?<p className="notice">No comparable: los tickets tienen composición animal distinta.</p>:r.data?.estado==='COMPARABLE'?<div className="metric-grid"><div className="metric"><span>Variación de peso</span><strong>{decimal(r.data.variacion_kg)} kg</strong></div><div className="metric"><span>Variación porcentual</span><strong>{decimal(r.data.variacion_pct)} %</strong></div></div>:<p className="notice">El servidor no entregó una comparación disponible.</p>}</State>;}
